insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-30','nieuw','Inkoop','Order versturen vanaf Inkoop, met foto''s erbij',
   'Staat een inkooporder of opdracht nog op "te versturen", dan open je hem op het tabblad Inkoop en verstuur je hem daar. Dat werkt ook op servicedeskbonnen, waar geen werkbegroting is. Bij het versturen kun je nu tot zes foto''s meesturen, bijvoorbeeld van de situatie ter plaatse.');
